 void refreshSession(String refresh){new Thread(()->{try{org.json.JSONObject d=new org.json.JSONObject();d.put("refresh_token",refresh);java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL("https://udwnmeqhwpnmwknjtssq.supabase.co/auth/v1/token?grant_type=refresh_token").openConnection();c.setRequestMethod("POST");c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("apikey","sb_publishable_7NgXp6OxMzUITMkzAf18Dw_sd-7_61x");c.getOutputStream().write(d.toString().getBytes("UTF-8"));int status=c.getResponseCode();java.io.InputStream in=status>=200&&status<300?c.getInputStream():c.getErrorStream();java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);org.json.JSONObject j=new org.json.JSONObject(new String(out.toByteArray(),"UTF-8"));c.disconnect();if(status>=200&&status<300){getSharedPreferences("tfc_auth",MODE_PRIVATE).edit().putString("access_token",j.optString("access_token")).putString("refresh_token",j.optString("refresh_token",refresh)).apply();}else if(status==400||status==401){getSharedPreferences("tfc_auth",MODE_PRIVATE).edit().clear().apply();runOnUiThread(()->{toast("Your session expired. Please sign in again.");login();});}}catch(Exception ignored){}}).start();}
