 void sendPasswordReset(String email){new Thread(()->{try{org.json.JSONObject d=new org.json.JSONObject();d.put("email",email);java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL("https://udwnmeqhwpnmwknjtssq.supabase.co/auth/v1/recover?redirect_to="+Uri.encode("thefirstcrush://login-callback")).openConnection();c.setRequestMethod("POST");c.setDoOutput(true);c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("apikey","sb_publishable_7NgXp6OxMzUITMkzAf18Dw_sd-7_61x");c.getOutputStream().write(d.toString().getBytes("UTF-8"));int status=c.getResponseCode();if(status>=200&&status<300)runOnUiThread(()->toast("Password reset email sent. Open the link to return to The First Crush."));else{java.io.InputStream in=c.getErrorStream();java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();if(in!=null){byte[] b=new byte[2048];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}String msg=new String(out.toByteArray(),"UTF-8");runOnUiThread(()->toast("Reset request failed: "+msg));}c.disconnect();}catch(Exception e){runOnUiThread(()->toast("Could not send reset email. Check your internet."));}}).start();}
