 void loadPosts(){String me=userId();api("GET","/rest/v1/posts?select=id,user_id,body,created_at&order=created_at.desc&limit=100",null,res->{try{org.json.JSONArray arr=new org.json.JSONArray(res);if(arr.length()==0){body.addView(txt("No community posts yet. Be the first to share 💗",14,MUTED,false));return;}for(int i=0;i<arr.length();i++){org.json.JSONObject p=arr.getJSONObject(i);String pid=p.optString("id","");String uid=p.optString("user_id","");String content=p.optString("body","");api("GET","/rest/v1/profiles?id=eq."+uid+"&select=full_name,username,avatar_url",null,pr->{String who="Community member";String avatar="";try{org.json.JSONArray pa=new org.json.JSONArray(pr);if(pa.length()>0){org.json.JSONObject prof=pa.getJSONObject(0);who=prof.optString("full_name","");if(who.isEmpty())who=prof.optString("username","Community member");avatar=prof.optString("avatar_url","");}}catch(Exception ignored){}post(pid,uid,who,avatar,content,me.equals(uid));});}}catch(Exception e){toast("Could not load community posts.");}});}
 void post(String postId,String ownerId,String who,String avatar,String content,boolean mine){LinearLayout c=col();c.setPadding(dp(16),dp(14),dp(16),dp(12));c.setBackground(shape(Color.WHITE,20));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(12);body.addView(c,p);c.addView(txt("♥  "+who,13,PURPLE,true));if(!avatar.isEmpty()){ImageView pic=new ImageView(this);pic.setImageResource(android.R.drawable.sym_def_app_icon);pic.setScaleType(ImageView.ScaleType.CENTER_CROP);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(dp(42),dp(42));ap.topMargin=dp(5);c.addView(pic,ap);loadAvatar(avatar,pic);}gap(c,12);c.addView(txt(content,16,INK,false));gap(c,12);LinearLayout a=row();a.addView(action("Share",()->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,content);startActivity(Intent.createChooser(i,"Share post"));}));if(mine)a.addView(action("🗑 Delete post",()->deletePost(postId)));c.addView(a);}
 void deletePost(String postId){new android.app.AlertDialog.Builder(this).setTitle("Delete post?").setMessage("This post will be removed from the community.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->api("DELETE","/rest/v1/posts?id=eq."+postId+"&user_id=eq."+userId(),null,res->{toast("Post deleted.");screen("Home");})).show();}

 void friends(){body.addView(txt("Find your people 💗",22,INK,true));gap(body,6);body.addView(txt("Search registered users by full name or username.",13,MUTED,false));gap(body,12);EditText search=field("Search name or username");body.addView(search);gap(body,8);LinearLayout results=col();body.addView(results);body.addView(action("Search",()->searchProfiles(search.getText().toString(),results)));search.setOnEditorActionListener((v,actionId,event)->{searchProfiles(search.getText().toString(),results);return true;});gap(body,18);body.addView(action("Incoming friend requests",()->loadIncomingRequests()));gap(body,8);body.addView(action("Refresh search",()->searchProfiles(search.getText().toString(),results)));searchProfiles("",results);}
 void searchProfiles(String term,LinearLayout results){String id=userId();if(id.isEmpty()){toast("Please sign in again.");return;}results.removeAllViews();String q=term==null?"":term.trim().replace("*","").replace(",","").replace("(","").replace(")","");String path="/rest/v1/profiles?select=id,username,full_name,bio,avatar_url&order=full_name.asc&limit=30";if(!q.isEmpty())path="/rest/v1/profiles?select=id,username,full_name,bio,avatar_url&or=(full_name.ilike.*"+Uri.encode(q)+"*,username.ilike.*"+Uri.encode(q)+"*)&order=full_name.asc&limit=30";api("GET",path,null,res->{try{org.json.JSONArray arr=new org.json.JSONArray(res);results.removeAllViews();int count=0;for(int i=0;i<arr.length();i++){org.json.JSONObject p=arr.getJSONObject(i);String uid=p.optString("id","");if(uid.equals(id))continue;count++;String name=p.optString("full_name","");String username=p.optString("username","");if(name.isEmpty())name=username.isEmpty()?"The First Crush user":username;LinearLayout card=col();card.setPadding(dp(14),dp(12),dp(14),dp(12));card.setBackground(shape(Color.WHITE,16));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=dp(8);results.addView(card,cp);card.addView(txt(name,16,INK,true));if(!username.isEmpty())card.addView(txt("@"+username,13,PURPLE,false));TextView requestButton=action("Checking request…",()->{});requestButton.setEnabled(false);card.addView(requestButton);String target=uid;String pair="/rest/v1/friend_requests?select=id,status,sender_id,receiver_id&or=(and(sender_id.eq."+id+",receiver_id.eq."+target+"),and(sender_id.eq."+target+",receiver_id.eq."+id+"))&limit=1";api("GET",pair,null,requestRes->{try{org.json.JSONArray requests=new org.json.JSONArray(requestRes);if(requests.length()==0){requestButton.setText("＋ Add friend");requestButton.setEnabled(true);requestButton.setOnClickListener(v->sendFriendRequest(target));return;}org.json.JSONObject req=requests.getJSONObject(0);String rid=req.optString("id","");String status=req.optString("status","pending");String sender=req.optString("sender_id","");if("accepted".equals(status)){requestButton.setText("✓ Friends · Remove");requestButton.setEnabled(true);requestButton.setOnClickListener(v->removeFriend(rid,requestButton));}else if("pending".equals(status)&&sender.equals(id)){requestButton.setText("Requested · Cancel");requestButton.setEnabled(true);requestButton.setOnClickListener(v->cancelFriendRequest(rid,requestButton,results,q));}else if("pending".equals(status)){requestButton.setText("Respond to request");requestButton.setEnabled(true);requestButton.setOnClickListener(v->loadIncomingRequests());}else{requestButton.setText("＋ Add friend");requestButton.setEnabled(true);requestButton.setOnClickListener(v->sendFriendRequest(target));}}catch(Exception ex){requestButton.setText("＋ Add friend");requestButton.setEnabled(true);requestButton.setOnClickListener(v->sendFriendRequest(target));}});}if(count==0)results.addView(txt(q.isEmpty()?"No other registered users yet.":"No users found. Try another name or username.",14,MUTED,false));}catch(Exception e){toast("Could not read search results.");}});}
 void removeFriend(String requestId,TextView button){new android.app.AlertDialog.Builder(this).setTitle("Remove friend?").setMessage("This person will be removed from your friends list.").setNegativeButton("Cancel",null).setPositiveButton("Remove",(d,w)->{button.setEnabled(false);api("DELETE","/rest/v1/friend_requests?id=eq."+requestId+"&status=eq.accepted",null,res->{toast("Friend removed.");screen("Friends");});}).show();}
 void sendFriendRequest(String target){try{org.json.JSONObject d=new org.json.JSONObject();d.put("sender_id",userId());d.put("receiver_id",target);d.put("status","pending");api("POST","/rest/v1/friend_requests",d,res->{toast("Friend request sent! 💗");screen("Friends");});}catch(Exception e){toast("Could not send friend request.");}}
 void cancelFriendRequest(String requestId,TextView button,LinearLayout results,String query){button.setEnabled(false);api("DELETE","/rest/v1/friend_requests?id=eq."+requestId+"&sender_id=eq."+userId(),null,res->{toast("Friend request cancelled.");searchProfiles(query,results);});}
 void loadIncomingRequests(){base("Friend Requests");body.addView(txt("People who want to connect with you",15,MUTED,false));String id=userId();api("GET","/rest/v1/friend_requests?select=id,sender_id,status,created_at&receiver_id=eq."+id+"&status=eq.pending&order=created_at.desc",null,res->{try{org.json.JSONArray arr=new org.json.JSONArray(res);if(arr.length()==0){body.addView(txt("No pending friend requests.",15,MUTED,false));return;}for(int i=0;i<arr.length();i++){org.json.JSONObject req=arr.getJSONObject(i);String rid=req.optString("id","");String sender=req.optString("sender_id","");LinearLayout card=col();card.setPadding(dp(12),dp(12),dp(12),dp(12));card.setBackground(shape(Color.WHITE,16));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=dp(8);body.addView(card,cp);TextView senderName=txt("Loading profile…",14,INK,false);card.addView(senderName);api("GET","/rest/v1/profiles?id=eq."+sender+"&select=full_name,username",null,profileRes->{try{org.json.JSONArray pa=new org.json.JSONArray(profileRes);if(pa.length()>0){org.json.JSONObject pp=pa.getJSONObject(0);String fn=pp.optString("full_name","");String un=pp.optString("username","");senderName.setText(fn.isEmpty()?(un.isEmpty()?sender:("@"+un)):fn+(un.isEmpty()?"":"  ·  @"+un));}else senderName.setText(sender);}catch(Exception ignored){senderName.setText(sender);}});TextView accept=action("Accept request",()->respondFriendRequest(rid,"accepted"));TextView reject=action("Reject request",()->respondFriendRequest(rid,"rejected"));card.addView(accept);card.addView(reject);}}catch(Exception e){toast("Could not load friend requests.");}});}
 void respondFriendRequest(String requestId,String status){try{org.json.JSONObject d=new org.json.JSONObject();d.put("status",status);api("PATCH","/rest/v1/friend_requests?id=eq."+requestId+"&receiver_id=eq."+userId(),d,res->{toast(status.equals("accepted")?"Friend request accepted!":"Friend request rejected.");loadIncomingRequests();});}catch(Exception e){toast("Could not update friend request.");}}
 void notifications(){for(String s:new String[]{"💗 Someone liked your post","👋 New friend request","💬 Someone commented","✨ Welcome to The First Crush"}){body.addView(txt(s,16,INK,false));gap(body,18);}}
 
