 String userId(){try{String[] p=accessToken().split("\\.");org.json.JSONObject j=new org.json.JSONObject(new String(android.util.Base64.decode(p[1],android.util.Base64.URL_SAFE|android.util.Base64.NO_WRAP|android.util.Base64.NO_PADDING),"UTF-8"));return j.optString("sub","");}catch(Exception e){return "";}}
 void api(String method,String path,org.json.JSONObject data,java.util.function.Consumer<String> done){new Thread(()->{String response="";try{java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL("https://udwnmeqhwpnmwknjtssq.supabase.co"+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestProperty("apikey","sb_publishable_7NgXp6OxMzUITMkzAf18Dw_sd-7_61x");c.setRequestProperty("Authorization","Bearer "+accessToken());c.setRequestProperty("Content-Type","application/json");if(data!=null){c.setDoOutput(true);if(method.equals("POST")||method.equals("PATCH"))c.setRequestProperty("Prefer","resolution=merge-duplicates,return=representation");c.getOutputStream().write(data.toString().getBytes("UTF-8"));}int status=c.getResponseCode();java.io.InputStream in=status>=200&&status<300?c.getInputStream():c.getErrorStream();if(in!=null){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);response=new String(out.toByteArray(),"UTF-8");}if(status<200||status>=300)throw new Exception(response);c.disconnect();String result=response;runOnUiThread(()->done.accept(result));}catch(Exception e){String err=e.getMessage()==null?"Network error":e.getMessage();runOnUiThread(()->toast("Server error: "+err));}}).start();}
