 @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==701&&resultCode==RESULT_OK&&data!=null&&data.getData()!=null){pickedAvatar=data.getData();if(profileAvatar!=null){try{java.io.InputStream in=getContentResolver().openInputStream(pickedAvatar);android.graphics.Bitmap bm=BitmapFactory.decodeStream(in);if(in!=null)in.close();profileAvatar.setImageBitmap(bm);}catch(Exception e){toast("Could not preview this image.");}}}}
 void uploadAvatar(String id,java.util.function.Consumer<String> done){if(pickedAvatar==null){done.accept(avatarUrl);return;}new Thread(()->{try{java.io.InputStream in=getContentResolver().openInputStream(pickedAvatar);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);in.close();byte[] raw=out.toByteArray();android.graphics.Bitmap source=BitmapFactory.decodeByteArray(raw,0,raw.length);if(source==null)throw new Exception("This image format could not be opened. Please choose a JPG or PNG photo.");int max=1600;float scale=Math.min(1f,Math.min((float)max/source.getWidth(),(float)max/source.getHeight()));android.graphics.Bitmap upload=scale<1f?android.graphics.Bitmap.createScaledBitmap(source,Math.max(1,(int)(source.getWidth()*scale)),Math.max(1,(int)(source.getHeight()*scale)),true):source;java.io.ByteArrayOutputStream jpg=new java.io.ByteArrayOutputStream();upload.compress(android.graphics.Bitmap.CompressFormat.JPEG,85,jpg);byte[] bytes=jpg.toByteArray();if(upload!=source)upload.recycle();source.recycle();String path=id+"/"+System.currentTimeMillis()+".jpg";java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL("https://udwnmeqhwpnmwknjtssq.supabase.co/storage/v1/object/avatars/"+path).openConnection();c.setRequestMethod("POST");c.setDoOutput(true);c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestProperty("apikey","sb_publishable_7NgXp6OxMzUITMkzAf18Dw_sd-7_61x");c.setRequestProperty("Authorization","Bearer "+accessToken());c.setRequestProperty("Content-Type","image/jpeg");c.setRequestProperty("x-upsert","true");c.getOutputStream().write(bytes);int status=c.getResponseCode();if(status<200||status>=300){java.io.InputStream er=c.getErrorStream();java.io.ByteArrayOutputStream eb=new java.io.ByteArrayOutputStream();if(er!=null){byte[] q=new byte[2048];int z;while((z=er.read(q))!=-1)eb.write(q,0,z);}throw new Exception(new String(eb.toByteArray(),"UTF-8"));}c.disconnect();String url="https://udwnmeqhwpnmwknjtssq.supabase.co/storage/v1/object/public/avatars/"+path;runOnUiThread(()->done.accept(url));}catch(Exception e){String m=e.getMessage()==null?"Upload failed":e.getMessage();runOnUiThread(()->toast("Photo upload failed: "+m));}}).start();}
 void loadAvatar(String url,ImageView target){if(url==null||url.isEmpty())return;new Thread(()->{try{java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL(url).openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);android.graphics.Bitmap bm=BitmapFactory.decodeStream(c.getInputStream());c.disconnect();if(bm!=null)runOnUiThread(()->target.setImageBitmap(bm));}catch(Exception ignored){}}).start();}
 void editProfile(){base("Edit profile");body.addView(txt("PROFILE PHOTO",12,MUTED,true));gap(body,8);profileAvatar=new ImageView(this);profileAvatar.setImageResource(android.R.drawable.sym_def_app_icon);profileAvatar.setScaleType(ImageView.ScaleType.CENTER_CROP);profileAvatar.setBackground(shape(0xffffe6f0,60));profileAvatar.setClipToOutline(true);LinearLayout.LayoutParams avp=new LinearLayout.LayoutParams(dp(104),dp(104));avp.gravity=Gravity.CENTER_HORIZONTAL;body.addView(profileAvatar,avp);body.addView(action("Choose photo",()->chooseAvatar()));EditText full=field("Full name"),user=field("Username"),bio=field("Bio (tell people about you)");bio.setSingleLine(false);bio.setMinHeight(dp(110));bio.setGravity(Gravity.TOP);bio.setPadding(dp(14),dp(12),dp(14),dp(12));gap(body,12);body.addView(txt("PROFILE DETAILS",12,MUTED,true));gap(body,8);body.addView(full);gap(body,10);body.addView(user);gap(body,10);body.addView(bio);gap(body,16);TextView save=primary("Save profile");body.addView(save);body.addView(action("Cancel",()->screen("Profile")));String id=userId();if(id.isEmpty()){toast("Please sign in again.");return;}api("GET","/rest/v1/profiles?id=eq."+id+"&select=full_name,username,bio,avatar_url",null,res->{try{org.json.JSONArray a=new org.json.JSONArray(res);if(a.length()>0){org.json.JSONObject p=a.getJSONObject(0);full.setText(p.optString("full_name",""));user.setText(p.optString("username",""));bio.setText(p.optString("bio",""));avatarUrl=p.optString("avatar_url","");loadAvatar(avatarUrl,profileAvatar);}}catch(Exception e){toast("Could not load profile details.");}});save.setOnClickListener(v->{save.setEnabled(false);uploadAvatar(id,url->{try{org.json.JSONObject p=new org.json.JSONObject();p.put("id",id);p.put("full_name",full.getText().toString().trim());p.put("username",user.getText().toString().trim().replace("@",""));p.put("bio",bio.getText().toString().trim());p.put("avatar_url",url);api("POST","/rest/v1/profiles?on_conflict=id",p,res->{pickedAvatar=null;avatarUrl=url;getSharedPreferences("tfc_profile",MODE_PRIVATE).edit().putString("full_name",full.getText().toString().trim()).putString("username",user.getText().toString().trim().replace("@","")).putString("bio",bio.getText().toString().trim()).putString("avatar_url",url).apply();toast("Profile saved successfully.");screen("Profile");});}catch(Exception e){save.setEnabled(true);toast("Could not save profile.");}});});}
